# Surfactant concentration, surface velocity, and bulk (subsurface) flow for a static
# suspension configuration. The surfactant and Stokes mobility problems are solved once,
# and the surface and bulk fields are evaluated from the same solution.
#
# The bulk flow (z < 0) is split as 𝐔 = 𝐔^S + 𝐔^M. 𝐔^S is the free-space 3D Stokeslet
# convolution of the particle force densities,
#
#     𝐔^S(𝐗) = ∫_Ω 𝐆_3D(𝐗 - 𝐘) · 𝐅(𝐘) dS_𝐘,   𝐅 = (2 f̃, 0)ᵀ,   𝐆_3D(𝐑) = (𝐈 + 𝐑̂𝐑̂)/(8π|𝐑|),
#
# evaluated with the domain quadrature of Ω and f̃ = f_body from the mobility solve.
# 𝐔^M is generated by the surfactant line force on Γ,
#
#     𝐮^M(x,y,z) = -∇_s[(½ I₋₃ + (z/2) I₋₂) * (δ_Γ σ)]
#     w^M(x,y,z) = -(z/2) I₋₂ * (δ_Γ σ)
#
# with I₋₃(r,z) = (1/2π)[-R - z log(R - z)], I₋₂(r,z) = -(1/2π) log(R - z), R = √(r²+z²).
# Differentiating in x, y gives the closed-form kernels
#
#     𝐮^M(x,y,z) = ∫_Γ (𝐱-𝐲) (R+z) / (4π R (R-z)) σ(𝐲) ds(𝐲),
#     w^M(x,y,z) = (z/4π) ∫_Γ log(R-z) σ(𝐲) ds(𝐲).
#
# Output: output/fields_<config>.dat, surface concentration and velocity
#   Line 1: # Nx=... Ny=... N=... a=... b=... alpha=...
#   Line 2: x values (Nx floats)
#   Line 3: y values (Ny floats)
#   Line 4: particle x centers (N floats)
#   Line 5: particle y centers (N floats)
#   Line 6: particle orientations θ (N floats)
#   Lines 7..(6+Ny):        ϕ matrix (concentration), Ny rows × Nx columns
#   Lines (7+Ny)..(6+2Ny):  u matrix (x-velocity)
#   Lines (7+2Ny)..(6+3Ny): v matrix (y-velocity)
#
# Output: output/bulk_<config>.dat, bulk velocity, one row per 3D grid point
#   Line 1: # Nx=... Ny=... Nz=...
#   Lines 2...: x y z u v w   (Nx*Ny*Nz rows, z ≤ 0)

using Random

include("../../src/marangoni.jl")

# -- Parameters ----------------------------------------------------------------

Ns   = 256
M    = 32
s₀   = π/2
g(s) = -cos(s)

aspect_ratio = 4.0
a = sqrt(aspect_ratio)
b = 1.0 / a

Ω, Γ_D, Γ_N = surfer(a, b, s₀, Ns, M)

# -- Configuration -------------------------------------------------------------

config = "lattice"
Random.seed!(1)

n_side = 4
d_lat  = 4.0   # lattice spacing
Nparticles = n_side^2

xcm = ComplexF64[d_lat * (i - (n_side+1)/2) + im * d_lat * (j - (n_side+1)/2)
                 for j in 1:n_side for i in 1:n_side]
θcm = 2π .* rand(Nparticles)

# -- Solve: surfactant + Stokes mobility ---------------------------------------

println("Solving surfactant...")
σ, ϕinf, Γ = surfactant_solve(xcm, θcm, Γ_D, Γ_N, g)

Npts = length(Ω.z)
offs = [0; cumsum(fill(Npts, Nparticles))]
pts  = [exp(im * θcm[i]) .* Ω.z .+ xcm[i] for i in 1:Nparticles]
u_pts, v_pts = ∇ℬ(vcat(vec.(pts)...), σ, Γ)

uinf = Vector{Tuple{Matrix{Float64}, Matrix{Float64}}}(undef, Nparticles)
for i in 1:Nparticles
    ri  = offs[i]+1:offs[i+1]
    shp = size(pts[i])
    uinf[i] = (reshape(copy(u_pts[ri]), shp), reshape(copy(v_pts[ri]), shp))
end

println("Solving Stokes mobility...")
F = [zeros(3) for _ in 1:Nparticles]
f_body, U = suspension_mobility_solve(xcm, θcm, uinf, nothing, F, Ω)

outdir = joinpath(@__DIR__, "output")
mkpath(outdir)

write_row(io, v) = println(io, join([@sprintf("%.10e", x) for x in v], " "))
function write_matrix(io, A)
    for irow in 1:size(A, 1)
        write_row(io, A[irow, :])
    end
end

# -- Surface fields: concentration + velocity on a grid ------------------------

pad  = 5.0
Nplt = 512

xplt_s = range(minimum(real.(xcm)) - pad, maximum(real.(xcm)) + pad, length=Nplt)
yplt_s = range(minimum(imag.(xcm)) - pad, maximum(imag.(xcm)) + pad, length=Nplt)
zg     = ComplexF64[xn + im*yn for yn in yplt_s, xn in xplt_s]

ϕ = sum(𝒱(zg, σ[2k-1], Γ[2k-1]) .+ 𝒱(zg, σ[2k], Γ[2k]) for k in 1:Nparticles) .+ ϕinf

println("Evaluating surface velocity field...")
u, v = ∇ℬ(zg, σ, Γ)   # Marangoni component

for k in 1:Nparticles
    z_body = ComplexF64.(exp(-im * θcm[k]) .* (zg .- xcm[k]))
    vel = 𝒮_st(z_body, f_body[k], Ω)
    u_b = real.(first.(vel))
    v_b = real.(last.(vel))
    ct = cos(θcm[k]); st = sin(θcm[k])
    u .+= ct .* u_b .- st .* v_b
    v .+= st .* u_b .+ ct .* v_b
end

# Mask points inside particles
for k in 1:Nparticles
    z_body = exp(-im * θcm[k]) .* (zg .- xcm[k])
    inside = (real.(z_body) / a).^2 .+ (imag.(z_body) / b).^2 .< 1.0
    ϕ[inside] .= NaN
    u[inside] .= NaN
    v[inside] .= NaN
end

fields_path = joinpath(outdir, "fields_$(config).dat")
open(fields_path, "w") do io
    @printf(io, "# Nx=%d Ny=%d N=%d a=%.6f b=%.6f s0=%.6f\n", Nplt, Nplt, Nparticles, a, b, s₀)
    write_row(io, xplt_s)
    write_row(io, yplt_s)
    write_row(io, real.(xcm))
    write_row(io, imag.(xcm))
    write_row(io, θcm)
    write_matrix(io, ϕ)
    write_matrix(io, u)
    write_matrix(io, v)
end
println("Wrote $fields_path")

# -- Bulk field: subsurface velocity on a 3D grid ------------------------------

# World-frame domain source points and forces (𝐅 = 2 f̃) for the Stokeslet term
Y  = vcat([exp(im * θcm[i]) .* Ω.z .+ xcm[i] for i in 1:Nparticles]...)
dw = vcat([real.(Ω.dz) for _ in 1:Nparticles]...)

F_world = vcat([exp(im * θcm[i]) .* (f_body[i][1] .+ im .* f_body[i][2]) for i in 1:Nparticles]...)
Fx, Fy = 2 .* real.(F_world), 2 .* imag.(F_world)

"Free-space 3D Stokeslet contribution from domain quadrature points Y (z=0) with force (Fx,Fy)."
function stokeslet_bulk(x, y, z, Y, dw, Fx, Fy)
    us = 0.0; vs = 0.0; ws = 0.0
    @inbounds for n in eachindex(Y)
        dx = x - real(Y[n]); dy = y - imag(Y[n])
        ρ2 = dx^2 + dy^2 + z^2
        ρ  = sqrt(ρ2)
        RF = dx * Fx[n] + dy * Fy[n]
        coef = dw[n] / (8π * ρ)
        us += coef * (Fx[n] + dx * RF / ρ2)
        vs += coef * (Fy[n] + dy * RF / ρ2)
        ws += coef * (z * RF / ρ2)
    end
    return us, vs, ws
end

"Surfactant line-force contribution from boundary Γ (density σ) at bulk point (x,y,z), z<0."
function marangoni_bulk(x, y, z, σs, Γs)
    um = 0.0; vm = 0.0; wm = 0.0
    for (σk, Γk) in zip(σs, Γs)
        @inbounds for n in eachindex(Γk.γ)
            dx = x - real(Γk.γ[n]); dy = y - imag(Γk.γ[n])
            r2 = dx^2 + dy^2
            R  = sqrt(r2 + z^2)
            wσ = σk[n] * Γk.dΓ[n]
            coef = (R + z) / (4π * R * (R - z))
            um += dx * coef * wσ
            vm += dy * coef * wσ
            wm += (z / (4π)) * log(R - z) * wσ
        end
    end
    return um, vm, wm
end

function bulk_velocity(x, y, z, Y, dw, Fx, Fy, σs, Γs)
    uS, vS, wS = stokeslet_bulk(x, y, z, Y, dw, Fx, Fy)
    uM, vM, wM = marangoni_bulk(x, y, z, σs, Γs)
    return uS + uM, vS + vM, wS + wM
end

Nx = 32; Ny = 32; Nz = 32

xplt_b = range(minimum(real.(xcm)) - pad, maximum(real.(xcm)) + pad, length=Nx)
yplt_b = range(minimum(imag.(xcm)) - pad, maximum(imag.(xcm)) + pad, length=Ny)
Lz     = 0.75 * (maximum(xplt_b) - minimum(xplt_b))   # matches figs/fig_schematic.m
zplt_b = range(-Lz, -0.05 * Lz, length=Nz)            # avoid clutter right at the interface

println("Evaluating bulk velocity field ($(Nx * Ny * Nz) points, $(length(Y)) sources)...")

rows = Matrix{Float64}(undef, Nx * Ny * Nz, 6)
irow = 0
for zval in zplt_b, yval in yplt_b, xval in xplt_b
    global irow += 1
    ub, vb, wb = bulk_velocity(xval, yval, zval, Y, dw, Fx, Fy, σ, Γ)
    rows[irow, :] .= (xval, yval, zval, ub, vb, wb)
end

bulk_path = joinpath(outdir, "bulk_$(config).dat")
open(bulk_path, "w") do io
    @printf(io, "# Nx=%d Ny=%d Nz=%d\n", Nx, Ny, Nz)
    for irow in 1:size(rows, 1)
        @printf(io, "%.10e %.10e %.10e %.10e %.10e %.10e\n", rows[irow, :]...)
    end
end
println("Wrote $bulk_path")
